interface NotificationSender {
    void send(String recipient, String message);
}

class EmailSender implements NotificationSender {
    private final String smtpHost;

    EmailSender(String smtpHost) {
        this.smtpHost = smtpHost;
    }

    @Override
    public void send(String recipient, String message) {
        System.out.println(
            "Sending EMAIL to " + recipient + " using " + smtpHost
        );
    }
}

class SmsSender implements NotificationSender {
    private final String providerApiKey;

    SmsSender(String providerApiKey) {
        this.providerApiKey = providerApiKey;
    }

    @Override
    public void send(String recipient, String message) {
        System.out.println("Sending SMS to " + recipient);
    }
}

class NotificationService {
    private final NotificationSender sender;

    NotificationService(NotificationSender sender) {
        this.sender = sender;
    }

    public void notifyUser(String userContact, String message) {
        sender.send(userContact, message);
    }
}

